from ta_moler.cmd.asimgr.genericasimgr import Genericasimgr


class GetLedStatus(Genericasimgr):
    """Get Led Status command class."""

    def __init__(self, ne, connection, prompt=None, newline_chars=None,
                 runner=None, pw=None, options=None):
        """
        Get Led Status command.

        :param ne: single IP address of one site.
        :param connection: moler connection to device,
            terminal when command is executed.
        :param prompt: expected prompt sending by
            device after command execution.
        :param newline_chars: Characters to split lines.
        :param runner: Runner to run command.
        :param pw: sets of credentials for the sites.
        :param options: other options as a string.
        """
        super(GetLedStatus, self).__init__(connection=connection,
                                           prompt=prompt,
                                           newline_chars=newline_chars,
                                           runner=runner)

        self.ne = ne
        self.pw = pw
        self.options = options

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send
            over connection to device.
        """
        cmd = f"./getLEDStatus.sh -ne {self.ne}"
        if self.pw:
            cmd = f"{cmd} -pw {self.pw}"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd


